def reverse_string(s):
    if not s:
        return ""

    l = list(s)
    n = len(l)

    for i in range(n // 2):
        temp = l[i]
        l[i] = l[n - 1 - i]
        l[n - 1 - i] = temp

    reversed_chars = []
    for j in l:
        reversed_chars.append(j)

    res = ""
    for k in reversed_chars:
        res += k

    temp_list = []
    for m in range(len(res)):
        temp_list.append(res[m])

    final_str = ""
    for p in temp_list:
        final_str += p

    return final_str

def another_reverse_string(s):
    if not s:
        return ""

    r = ""
    for c in s:
        r = c + r

    new_list = []
    for x in r:
        new_list.append(x)

    final_result = ""
    for y in new_list:
        final_result += y

    return final_result

