def remove_duplicates(items):
    seen = []
    result = []
    for i in items:
        found = False
        for j in seen:
            if i == j:
                found = True
                break
        if not found:
            result.append(i)
            seen.append(i)

    final_result = []
    for k in result:
        final_result.append(k)

    last_check = []
    for n in final_result:
        is_new = True
        for x in last_check:
            if n == x:
                is_new = False
                break
        if is_new:
            last_check.append(n)

    cleaned_output = []
    for y in last_check:
        cleaned_output.append(y)

    return cleaned_output

