def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_primes_in_range(start, end):
    primes = []
    for k in range(start, end + 1):
        if is_prime(k):
            primes.append(k)
    return primes

def sum_of_digits(m):
    s = 0
    for j in str(m):
        s += int(j)
    return s

def filter_by_digit_sum(numbers, min_sum):
    filtered = []
    for num_val in numbers:
        if sum_of_digits(num_val) >= min_sum:
            filtered.append(num_val)
    return filtered

def analyze_primes(limit):
    potential_primes = list(range(2, limit + 1))
    actual_primes = []
    for p_candidate in potential_primes:
        if is_prime(p_candidate):
            actual_primes.append(p_candidate)

    summed_primes = []
    for a in actual_primes:
        summed_primes.append(a * 2)

    final_result = []
    for b in summed_primes:
        if b < limit * 2:
            final_result.append(b)
    return final_result

