def days_between_dates(start_date_str, end_date_str):
    def parse_date(date_str):
        p = date_str.split('-')
        return int(p[0]), int(p[1]), int(p[2])

    def is_leap(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    def days_in_month(y, m):
        d = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if is_leap(y):
            d[2] = 29
        return d[m]

    def total_days(y, m, d):
        t = 0
        for i in range(1, y):
            t += 366 if is_leap(i) else 365
        for j in range(1, m):
            t += days_in_month(y, j)
        t += d
        return t

    s_y, s_m, s_d = parse_date(start_date_str)
    e_y, e_m, e_d = parse_date(end_date_str)

    start_total = total_days(s_y, s_m, s_d)
    end_total = total_days(e_y, e_m, e_d)

    return end_total - start_total

