def longest_common_prefix(strings: list[str]) -> str:
    if not strings:
        return ""

    if len(strings) == 1:
        return strings[0]

    min_len = float('inf')
    for s in strings:
        if len(s) < min_len:
            min_len = len(s)

    prefix = ""
    for i in range(min_len):
