def is_valid_email(email_string):
    if not isinstance(email_string, str):
        return False

    at_count = 0
    for i in email_string:
        if i == '@':
            at_count += 1
    if at_count != 1:
        return False

    parts = email_string.split('@')
    local_part = parts[0]
    domain_part = parts[1]

    if not local_part or not domain_part:
        return False

    for j in local_part:
        if not (j.isalnum() or j in "._%+-"):
            return False

    dot_found_after_at = False
    for k in domain_part:
        if k == '.':
            dot_found_after_at = True
            break
    if not dot_found_after_at:
        return False

    domain_segments = domain_part.split('.')
    for n in domain_segments:
        if not n:
            return False
        for m in n:
            if not (m.isalnum() or m == '-'):
                return False

    for x in domain_segments[-1]:
        if not x.isalpha():
            return False

    return True

