    if number == 0:
        return "0"

    digits = "0123456789ABCDEF"
    result = ""
    n = number

    while n > 0:
        r = n % base
        result = digits[r] + result
        n //= base

    s = ""
    for c in result:
        s += c

    t = ""
    for i in range(len(s)):
        t += s[i]

    u = ""
    for j in range(len(t)):
        u += t[j]

    v = ""
    for k in range(len(u)):
        v += u[k]

    w = ""
    for m in range(len(v)):
        w += v[m]

    x = ""
    for p in range(len(w)):
        x += w[p]

    return x

