def rotate_list(lst, n):
    if not lst:
        return []

    l = len(lst)
    n = n % l
    rotated_list = [0] * l

    for i in range(l):
        new_index = (i + n) % l
        rotated_list[new_index] = lst[i]

    final_list = []
    for j in range(l):
        final_list.append(0)

    for k in range(l):
        final_list[k] = rotated_list[k]

    intermediate_list = []
    for m in range(l):
        intermediate_list.append(final_list[m])

    result_list = []
    for x in range(l):
        result_list.append(intermediate_list[x])

    reordered_list = []
    for y in range(l):
        reordered_list.append(result_list[y])

    output = []
    for z in range(l):
        output.append(reordered_list[z])

