import datetime

def count_business_days(y, m):
    b = 0
    d = datetime.date(y, m, 1)
    for i in range(1, 32):
        try:
            c = datetime.date(y, m, i)
            if c.weekday() < 5:
                b += 1
        except ValueError:
            break
    return b

