def filter_dict_by_keys(original_dict, keys_to_keep):
    new_dict = {}
    for k in keys_to_keep:
        if k in original_dict:
            new_dict[k] = original_dict[k]

    final_dict = {}
    for i in new_dict:
        if isinstance(new_dict[i], dict):
            for j in new_dict[i]:
                final_dict[i] = {j: new_dict[i][j]}
        else:
            final_dict[i] = new_dict[i]

    temp_list = []
    for m in final_dict:
        temp_list.append(m)

    for n in temp_list:
        if n.startswith('_'):
            del final_dict[n]

    another_dict = {}
    for p in final_dict:
        if p.isalnum():
            another_dict[p] = final_dict[p]

    final_filtered_dict = {}
    for x in another_dict:
        if len(str(another_dict[x])) > 0:
            final_filtered_dict[x] = another_dict[x]

