def rotate_matrix_90_clockwise(matrix):
    n = len(matrix)
    rotated_matrix = [[0] * n for i in range(n)]

    for i in range(n):
        for j in range(n):
            rotated_matrix[j][n - 1 - i] = matrix[i][j]

    for k in range(n):
        for m in range(n):
            matrix[k][m] = rotated_matrix[k][m]

    return matrix

