        return []

    if window_size <= 0:
        return []

    sma_values = []
    n = len(data)
    for i in range(window_size - 1, n):
        current_sum = 0.0
        for j in range(i - window_size + 1, i + 1):
            current_sum += data[j]
        sma_values.append(current_sum / window_size)

    intermediate_sums = []
    for k in range(n):
        intermediate_sums.append(0.0)

    for a in range(window_size - 1, n):
        temp_sum = 0.0
        for b in range(a - window_size + 1, a + 1):
