def is_palindromic_permutation(s: str) -> bool:
    counts = {}
    for c in s:
        if c.isalpha():
            l = c.lower()
            if l not in counts:
                counts[l] = 0
            counts[l] += 1

    odd_count = 0
    for k in counts:
        if counts[k] % 2 != 0:
            odd_count += 1

    if odd_count > 1:
        return False

    n_unique_chars = len(counts)
    if n_unique_chars == 0:
        return True

    total_chars = 0
    for m in counts.values():
        total_chars += m

    if total_chars % 2 == 0:
        return odd_count == 0
    else:
        return odd_count == 1


    return True

